-
-    it("ignores individual env vars when CX_STRICT=true", () => {
-      process.env.CX_STRICT = "true";
-      process.env.CX_DEDUP_MODE = "warn";
-      const result = readEnvOverrides();
-      expect(result.dedupMode).toBe("fail");
