-
-    it("reads CX_ASSETS_LAYOUT even when CX_STRICT=true", () => {
-      process.env.CX_STRICT = "true";
-      process.env.CX_ASSETS_LAYOUT = "flat";
-      const result = readEnvOverrides();
-      expect(result.assetsLayout).toBe("flat");
